import fs from 'node:fs';
import path from 'node:path';
const project = path.resolve(import.meta.dirname, '..');
const rows = fs.readFileSync(path.join(project, 'evidence/timings.jsonl'), 'utf8').trim().split('\n').map(line => JSON.parse(line));
const lines = [
  '# Recorded timings', '',
  'Generated by `node scripts/report-timings.mjs` from `evidence/timings.jsonl`.', '',
  'Each log starts with the exact command. Source fetching, failed attempts, and the explicitly stopped retry are retained. Some stages are nested or overlapped, so adding all durations does not give elapsed wall-clock time.', '',
  '| Started (UTC) | Stage | Seconds | Exit | Log |',
  '| --- | --- | ---: | ---: | --- |',
  ...rows.map(r => `| ${r.start} | ${r.stage} | ${r.seconds.toFixed(3)} | ${r.exit_code} | [log](${path.relative(project, r.log)}) |`),
  '',
  'Exit 0 means that command completed successfully, not that all release checks passed. Exit 137 in this record is the explicitly stopped build container; see PORTING.md and the corresponding logs.', ''
];
fs.writeFileSync(path.join(project, 'TIMINGS.md'), lines.join('\n'));
console.log(`Wrote TIMINGS.md with ${rows.length} completed stages.`);
